<?php
declare(strict_types=1);
namespace Tests\Integration;
use PDO;use PHPUnit\Framework\TestCase;
if(!defined('CLUB_MIGRATION_MEMORY_TEST'))define('CLUB_MIGRATION_MEMORY_TEST',true);
require_once dirname(__DIR__,2).'/includes/club_migration.php';
require_once dirname(__DIR__,2).'/includes/club_migration_finance.php';
final class ClubMigrationFinanceTest extends TestCase {
 private PDO $p;private array $session;
 protected function setUp():void{$this->session=$_SESSION??[];$_SESSION=['trener_id'=>1,'staff_positions'=>['finance_manager','catalog_manager'],'staff_active_position'=>'finance_manager'];$p=$this->p=new PDO('sqlite::memory:',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);$p->exec("CREATE TABLE treneri(id INT PRIMARY KEY,aktivni INT);INSERT INTO treneri VALUES(1,1),(2,1);CREATE TABLE staff_user_positions(trainer_id INT,position_code TEXT);INSERT INTO staff_user_positions VALUES(1,'finance_manager'),(1,'catalog_manager'),(2,'coach');CREATE TABLE staff_superadmins(trainer_id INT);CREATE TABLE shop_products(id INT PRIMARY KEY,offer_type TEXT,name TEXT);INSERT INTO shop_products VALUES(1,'goods','LOCALHOST shirt');CREATE TABLE shop_variants(id INT PRIMARY KEY,product_id INT,sku TEXT,unit_code TEXT,stock_quantity_decimal TEXT);INSERT INTO shop_variants VALUES(1,1,'TEST-SKU','piece','17');CREATE TABLE verejni_uzivatele(id INT PRIMARY KEY);INSERT INTO verejni_uzivatele VALUES(41);CREATE TABLE sportovci(id INT PRIMARY KEY);INSERT INTO sportovci VALUES(17);CREATE TABLE shop_orders(id INT PRIMARY KEY,account_id INT,total_minor INT,currency TEXT,status TEXT,payment_status TEXT);INSERT INTO shop_orders VALUES(1,41,10000,'CZK','placed','unpaid');CREATE TABLE shop_order_items(id INT PRIMARY KEY,order_id INT,variant_id INT,quantity INT);INSERT INTO shop_order_items VALUES(1,1,1,2);CREATE TABLE payments(id INT PRIMARY KEY,payable_type TEXT,payable_id INT,variable_symbol TEXT,status TEXT);INSERT INTO payments VALUES(1,'shop_order',1,'0000123456','pending');");foreach(['20261022220000_accounting_ledger','20261022221000_accounting_documents','20261022230000_shop_inventory','20261023050000_club_expenses','20261023060000_club_rewards','20261023080000_club_migration'] as $m){$migration=require dirname(__DIR__,2).'/migrations/'.$m.'.php';$migration['up']($p);self::assertTrue($migration['verify']($p));}\shopInventoryConfigure($p,1,'LOCALHOST warehouse','fifo','LOCALHOST accountant valuation','LOCALHOST inventory approval',true);}
 protected function tearDown():void{$_SESSION=$this->session;}
 private function proposal(array $over=[]):array{return array_replace(['mapping_evidence'=>'LOCALHOST explicit source identity match','counterparty_evidence'=>'LOCALHOST verified counterparties'],$over);}
 private function stage(string $type,array $data,string $source='source-1',string $window='2026-10-22 12:00:00'):array{if(str_ends_with($type,'_link')){try{$target=\clubMigrationFinanceTarget($this->p,$type,1);foreach(\clubMigrationFinanceCounterparties($this->p,$target) as $role=>$binding)$data['counterparties'][$role]='SOURCE-'.$role;}catch(\Throwable){}}$id=\clubMigrationStage($this->p,['contract'=>'club-migration.synthetic.v1','synthetic_only'=>true,'timezone'=>'Europe/Prague','source_namespace'=>'TEST-ORIGINAL','window_from'=>'2026-10-01 00:00:00','window_to'=>$window,'records'=>[['type'=>$type,'source_id'=>$source,'data'=>$data]]],1);$q=$this->p->prepare('SELECT * FROM club_migration_items WHERE batch_id=?');$q->execute([$id]);return $q->fetch();}
 private function review(array $i,array $proposal):array{if(!empty($proposal['target_id'])&&str_ends_with($i['entity_type'],'_link')&&!isset($proposal['counterparties'])){$target=\clubMigrationFinanceTarget($this->p,$i['entity_type'],(int)$proposal['target_id']);foreach(\clubMigrationFinanceCounterparties($this->p,$target) as $role=>$binding)$proposal['counterparties'][$role]=['source_id'=>'SOURCE-'.$role,'target_kind'=>$binding['kind'],'target_id'=>$binding['id'],'evidence'=>'LOCALHOST explicit fixture identity map'];}return \clubMigrationReview($this->p,(int)$i['id'],(int)$i['revision'],'approve',$proposal,$i['source_hash'],1,'LOCALHOST exact preview verified');}
 private function apply(array $i):array{return \clubMigrationApply($this->p,(int)$i['batch_id'],\clubMigrationPlanHash($this->p,(int)$i['batch_id']),1);}
 private function deny(callable $fn):void{try{$fn();self::fail('Expected safe refusal');}catch(\DomainException|\AccountingLedgerException|\ShopInventoryException $e){self::assertNotSame('',$e->getMessage());}}
 private function account():array{return ['code'=>'TEST-OPEN','name'=>'TEST bank','kind'=>'bank','currency'=>'CZK','opened_on'=>'2026-10-01','opening_minor'=>1234500,'evidence'=>'LOCALHOST signed statement opening'];}
 public function testAccountOpeningIsNotIncomeAndRepeatedSourceAcrossBatchesLinksOnce():void{$data=$this->account();$i=$this->stage('finance_account_opening',$data);$proposal=$this->proposal(['opening_approval_evidence'=>'LOCALHOST accountant confirmed opening']);$i=$this->review($i,$proposal);$report=$this->apply($i);self::assertSame('rehearsal_complete',$report['state']);self::assertSame(1234500,(int)$this->p->query('SELECT opening_minor FROM accounting_accounts')->fetchColumn());self::assertSame(0,(int)$this->p->query('SELECT COUNT(*) FROM accounting_movements')->fetchColumn());$again=$this->stage('finance_account_opening',$data,'source-1','2026-10-22 13:00:00');$again=$this->review($again,$proposal);$this->apply($again);self::assertSame(1,(int)$this->p->query('SELECT COUNT(*) FROM accounting_accounts')->fetchColumn());self::assertSame(1,(int)$this->p->query('SELECT COUNT(*) FROM club_migration_maps')->fetchColumn());}
 public function testStockPhysicalOpeningPreservesReservationsAndNeverTreatsAvailableAsPhysical():void{$data=['sku'=>'TEST-SKU','physical_quantity'=>5,'blocked_quantity'=>1,'reserved_quantity'=>2,'unit_cost_minor'=>null,'effective_on'=>'2026-10-01','evidence'=>'LOCALHOST counted five physical pieces'];$i=$this->stage('finance_stock_opening',$data);$i=$this->review($i,$this->proposal(['variant_id'=>1,'reservations'=>[1=>2],'inventory_approval_evidence'=>'LOCALHOST signed count and orders']));$this->apply($i);$b=\shopInventoryBalance($this->p,1);self::assertSame([5,2,1,2],[$b['physical_quantity'],$b['reserved_quantity'],$b['blocked_quantity'],$b['available_quantity']]);self::assertSame('pending',$this->p->query('SELECT status FROM payments')->fetchColumn());self::assertSame('0000123456',$this->p->query('SELECT variable_symbol FROM payments')->fetchColumn());self::assertSame(0,(int)$this->p->query('SELECT COUNT(*) FROM accounting_movements')->fetchColumn());}
 public function testUnmappedReservationOrHarrachovConflictCannotApprove():void{$data=['sku'=>'TEST-SKU','physical_quantity'=>5,'blocked_quantity'=>1,'reserved_quantity'=>2,'unit_cost_minor'=>null,'effective_on'=>'2026-10-01','evidence'=>'LOCALHOST count'];$i=$this->stage('finance_stock_opening',$data);$this->deny(fn()=>$this->review($i,$this->proposal(['variant_id'=>1,'reservations'=>[],'inventory_approval_evidence'=>'LOCALHOST inventory proof'])));$i=$this->stage('finance_account_opening',$this->account()+['conflicts'=>['Harrachov advances 0 vs 200000 minor']],'Harrachov');$this->deny(fn()=>$this->review($i,$this->proposal(['opening_approval_evidence'=>'LOCALHOST signed count'])));self::assertSame(0,(int)$this->p->query('SELECT COUNT(*) FROM accounting_accounts')->fetchColumn());}
 public function testChangedTargetAfterPreviewBlocksWholeOpening():void{$data=['sku'=>'TEST-SKU','physical_quantity'=>5,'blocked_quantity'=>1,'reserved_quantity'=>2,'unit_cost_minor'=>1000,'effective_on'=>'2026-10-01','evidence'=>'LOCALHOST count'];$i=$this->stage('finance_stock_opening',$data);$i=$this->review($i,$this->proposal(['variant_id'=>1,'reservations'=>[1=>2],'inventory_approval_evidence'=>'LOCALHOST verified count']));$this->p->exec('UPDATE shop_order_items SET quantity=3 WHERE id=1');$this->deny(fn()=>$this->apply($i));self::assertSame(0,(int)$this->p->query('SELECT COUNT(*) FROM shop_stock_balances')->fetchColumn());self::assertSame('17',$this->p->query('SELECT stock_quantity_decimal FROM shop_variants')->fetchColumn());}
 public function testOrderLinkPreservesVsPaymentAndRejectsNewerTargetMutation():void{$summary=\clubMigrationFinanceSummary(\clubMigrationFinanceTarget($this->p,'finance_order_link',1));$data=['expected'=>array_intersect_key($summary,array_flip(['account_id','total_minor','currency','status','payment_status','variable_symbols','items_hash','reservations_hash']))];$i=$this->stage('finance_order_link',$data);$proposal=$this->proposal(['target_id'=>1,'completion_system'=>'kis','completion_owner_trainer_id'=>1]);$i=$this->review($i,$proposal);$this->apply($i);self::assertSame('pending',$this->p->query('SELECT status FROM payments')->fetchColumn());self::assertSame('0000123456',$this->p->query('SELECT variable_symbol FROM payments')->fetchColumn());$again=$this->stage('finance_order_link',$data,'source-1','2026-10-22 13:00:00');$this->p->exec("UPDATE shop_orders SET status='processing' WHERE id=1");$this->deny(fn()=>$this->review($again,$proposal));self::assertSame(1,(int)$this->p->query('SELECT COUNT(*) FROM shop_orders')->fetchColumn());}
 public function testMissingActiveOrderHasExplicitLegacyCompletionBlocker():void{$i=$this->stage('finance_order_link',['expected'=>['variable_symbols'=>['0012345678']]],'OLD-ORDER-42');$b=\clubMigrationBatch($this->p,(int)$i['batch_id']);$preview=\clubMigrationFinancePreview($this->p,'finance_order_link',$b,$i,json_decode($i['payload_json'],true),$this->proposal(['completion_system'=>'legacy','completion_owner_trainer_id'=>1]));self::assertTrue($preview['normalized']['legacy_completion']['stop_flag']);self::assertSame('OLD-ORDER-42',$preview['normalized']['legacy_completion']['source_id']);self::assertSame(['0012345678'],$preview['normalized']['legacy_completion']['variable_symbols']);self::assertNotEmpty($preview['issues']);}
 public function testSameSourceChangedContentAndRevokedRoleCannotOpenMoney():void{$i=$this->stage('finance_account_opening',$this->account());$proposal=$this->proposal(['opening_approval_evidence'=>'LOCALHOST confirmed balance']);$i=$this->review($i,$proposal);$this->p->exec("DELETE FROM staff_user_positions WHERE trainer_id=1 AND position_code='finance_manager'");$this->deny(fn()=>$this->apply($i));self::assertSame(0,(int)$this->p->query('SELECT COUNT(*) FROM accounting_accounts')->fetchColumn());}
 public function testHistoricalDocumentWithoutVerifiedOriginalIsNotReissued():void{$this->p->exec("INSERT INTO accounting_documents(kind,source_type,source_id,idempotency_key,status,number,snapshot_json,snapshot_sha256,total_minor,currency,effective_on,created_by) VALUES('invoice','legacy',99,'legacy-99','issued','OLD-2009-42','{}','hash',50000,'CZK','2026-10-01',1)");$data=['expected'=>['number'=>'OLD-2009-42','total_minor'=>50000,'currency'=>'CZK','snapshot_sha256'=>'hash','pdf_sha256'=>null]];$i=$this->stage('finance_document_link',$data);$this->deny(fn()=>$this->review($i,$this->proposal(['target_id'=>1])));self::assertSame(1,(int)$this->p->query('SELECT COUNT(*) FROM accounting_documents')->fetchColumn());self::assertSame(0,(int)$this->p->query('SELECT COUNT(*) FROM accounting_document_series')->fetchColumn());}
 public function testExpenseAdvanceAndRewardReconcileLinksDoNotRecalculateOrCreateMoney():void {
  $this->p->exec("INSERT INTO treneri VALUES(3,1);INSERT INTO staff_user_positions VALUES(2,'finance_manager')");
  $c=\clubExpenseCreateCase($this->p,['title'=>'LOCALHOST Harrachov resolved','leader_trainer_id'=>3,'due_on'=>'2026-10-31','evidence'=>'LOCALHOST source review'],1,'LOCALHOST verified financial case',true);
  $a=\clubExpenseCreateAdvance($this->p,['case_id'=>$c['id'],'recipient_kind'=>'trainer','recipient_id'=>3,'recipient_label'=>'LOCALHOST recipient','payee_evidence'=>'LOCALHOST original handoff proof','limit_minor'=>200000,'due_on'=>'2026-10-31','purpose'=>'LOCALHOST original event','request_key'=>'advance-one'],1,'LOCALHOST actual advance request',true);\clubExpenseAdvanceTransition($this->p,(int)$a['id'],'approve',2,'LOCALHOST independent approval',true);
  $summary=\clubMigrationFinanceSummary(\clubMigrationFinanceTarget($this->p,'finance_advance_link',(int)$a['id']));$data=['expected'=>array_intersect_key($summary,array_flip(['recipient_kind','recipient_id','recipient_label','currency','limit_minor','out_minor','returned_minor','consumed_minor','transferred_minor','balance_minor']))];$i=$this->stage('finance_advance_link',$data,'ADVANCE-2000');$i=$this->review($i,$this->proposal(['target_id'=>$a['id']]));$this->apply($i);self::assertSame(0,\clubExpenseAdvanceBalance($this->p,(int)$a['id'])['out_minor']);
  $this->p->exec("INSERT INTO club_reward_rules(id,kind,unit,rate_minor,valid_from,valid_to,title,approval_evidence,accounting_method,approved_by) VALUES(1,'athlete','training',100,'2020-01-01','2020-12-31','LOCALHOST historical rule','LOCALHOST old approval','LOCALHOST actual method',1);INSERT INTO club_reward_claims(id,kind,subject_id,date_from,date_to,currency,current_version_id,approved_version_id,created_by) VALUES(1,'athlete',17,'2020-01-01','2020-01-31','CZK',1,1,1);INSERT INTO club_reward_versions(id,claim_id,version,rule_id,amount_minor,recipient_kind,recipient_id,recipient_evidence,source_hash,snapshot_json,reason,submitted_by,request_key,request_hash) VALUES(1,1,1,1,700,'person',17,'LOCALHOST old recipient','historical-source','{}','LOCALHOST old approved amount',1,'old-reward','old-hash')");
  $summary=\clubMigrationFinanceSummary(\clubMigrationFinanceTarget($this->p,'finance_reward_link',1));$data=['expected'=>array_intersect_key($summary,array_flip(['currency','kind','subject_id','date_from','date_to','approved_minor','paid_minor','remaining_minor']))];$i=$this->stage('finance_reward_link',$data,'REWARD-2020');$i=$this->review($i,$this->proposal(['target_id'=>1]));$this->apply($i);self::assertSame(700,(int)$this->p->query('SELECT amount_minor FROM club_reward_versions')->fetchColumn());self::assertSame(0,(int)$this->p->query('SELECT COUNT(*) FROM accounting_movements')->fetchColumn());self::assertSame(0,(int)$this->p->query('SELECT COUNT(*) FROM club_reward_payouts')->fetchColumn());
 }

