  $summary=\clubMigrationFinanceSummary(\clubMigrationFinanceTarget($this->p,'finance_order_link',1));$data=['expected'=>array_intersect_key($summary,array_flip(['account_id','total_minor','currency','status','payment_status','variable_symbols','items_hash','reservations_hash']))];$i=$this->stage('finance_order_link',$data);$proposal=$this->proposal(['target_id'=>1,'completion_system'=>'kis','completion_owner_trainer_id'=>1,'counterparties'=>['buyer'=>['source_id'=>'SOURCE-buyer','target_kind'=>'account','target_id'=>999,'evidence'=>'LOCALHOST wrong target account']]]);$this->deny(fn()=>$this->review($i,$proposal));self::assertSame(0,(int)$this->p->query('SELECT COUNT(*) FROM club_migration_maps')->fetchColumn());self::assertSame(41,(int)$this->p->query('SELECT account_id FROM shop_orders')->fetchColumn());
 }
 public function testChangedMappedPersonInvalidatesFinancialReview():void {
  $i=$this->stage('finance_account_opening',$this->account());$target=\clubMigrationSportsTarget($this->p,'person',17);$this->p->prepare('INSERT INTO club_migration_maps(source_namespace,entity_type,source_id,source_hash,target_type,target_id,target_hash,item_id) VALUES(?,?,?,?,?,?,?,?)')->execute(['TEST-ORIGINAL','person','OLD-PERSON','fixture-source','person',17,\clubMigrationHash($target),$i['id']]);$this->p->exec("ALTER TABLE sportovci ADD COLUMN jmeno TEXT;UPDATE sportovci SET jmeno='Changed identity' WHERE id=17");$proposal=$this->proposal(['opening_approval_evidence'=>'LOCALHOST confirmed opening','identity_maps'=>[['source_type'=>'person','source_id'=>'OLD-PERSON','target_type'=>'person','target_id'=>17]]]);$this->deny(fn()=>$this->review($i,$proposal));self::assertSame(0,(int)$this->p->query('SELECT COUNT(*) FROM accounting_accounts')->fetchColumn());
